R.faktai_ar_testinis:
function ar_testinis( $order ) {
		if ( self::aplinka() !== 'prod' ) { return 1; }
		$sar = (string) get_option( self::OPT_TESTINIAI, '' );
		if ( $sar !== '' ) {
			$em = strtolower( trim( (string) $order->get_billing_email() ) );
			foreach ( preg_split( '/[\s,;]+/', strtolower( $sar ) ) as $t ) {
				if ( $t !== '' && $t === $em ) { return 1; }
			}
		}
		/* VERSLO diena — vietiniu laiku, nes `ps_stat_pradzia` yra ta diena,
		   kuria Raimis mato kalendoriuje, ne UTC. */
		$pr = (string) get_option( self::OPT_PRADZIA, '' );
		if ( $pr !== '' ) {
			$d = $order->get_date_created();
			if ( $d && wp_date( 'Y-m-d', $d->getTimestamp() ) < $pr ) { return 1; }
		}
		return 0;
	}

	private static function email_hash( $order ) {
		$e = strtolower( trim( (string) $order->get_billing_email() ) );
		return $e === '' ? '' : hash( 'sha256', $e );
	}

