{
    $orderStatus = str_replace('wc-', '', $status);
    $order->update_status(
        $orderStatus,
        __(
            PayseraPaths::PAYSERA_MESSAGE . 'Status changed to ',
            PayseraPaths::PAYSERA_TRANSLATIONS
        ) . $orderStatus,
        true
    );
}

